steps.codeExample:
# main.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    digitalocean = {
      source  = "digitalocean/digitalocean"
      version = "~> 2.0"
    }
  }
}

# Configure the DigitalOcean Provider
provider "digitalocean" {
  # Token is read from DIGITALOCEAN_TOKEN environment variable
}

# Variables
variable "droplet_name" {
  description = "Name of the droplet"
  type        = string
  default     = "web-server-demo"
}

variable "region" {
  description = "DigitalOcean region"
  type        = string
  default     = "nyc3"  # New York 3
}

variable "droplet_size" {
  description = "Droplet size/plan"
  type        = string
  default     = "s-1vcpu-1gb"  # $6/month - 1 vCPU, 1GB RAM
}

# Generate SSH key pair (run in terminal)
ssh-keygen -t ed25519 -f ~/.ssh/terraform-demo -C "terraform-demo" -N ""

# Add to main.tf:

# SSH Key
resource "digitalocean_ssh_key" "terraform_demo" {
  name       = "Terraform Demo Key"
  public_key = file("~/.ssh/terraform-demo.pub")
}

# Alternative: Use existing SSH key
# resource "digitalocean_ssh_key" "terraform_demo" {
#   name       = "Terraform Demo Key"
#   public_key = file("~/.ssh/id_rsa.pub")
# }

# Add to main.tf:

# Droplet
resource "digitalocean_droplet" "web" {
  name   = var.droplet_name
  image  = "ubuntu-22-04-x64"
  region = var.region
  size   = var.droplet_size

  ssh_keys = [
    digitalocean_ssh_key.terraform_demo.fingerprint
  ]

  user_data = <<-EOF
    #!/bin/bash
    apt-get update
    apt-get install -y nginx

    # Create custom HTML page
    cat > /var/www/html/index.html <<HTML
    <!DOCTYPE html>
    <html>
    <head>
        <title>Terraform Demo</title>
        <style>
            body {
                font-family: Arial, sans-serif;
                display: flex;
                justify-content: center;
                align-items: center;
                height: 100vh;
                margin: 0;
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                color: white;
            }
            .container {
                text-align: center;
                padding: 2rem;
                background: rgba(255, 255, 255, 0.1);
                border-radius: 10px;
                backdrop-filter: blur(10px);
            }
            h1 { margin: 0 0 1rem 0; }
            p { margin: 0.5rem 0; }
            .success { color: #4ade80; font-weight: bold; }
        </style>
    </head>
    <body>
        <div class="container">
            <h1>🚀 Terraform Deployment Successful!</h1>
            <p class="success">✓ Droplet Created</p>
            <p class="success">✓ Nginx Installed</p>
            <p class="success">✓ Web Server Running</p>
            <p style="margin-top: 2rem; opacity: 0.8;">
                Hostname: $(hostname)
            </p>
        </div>
    </body>
    </html>
HTML

    systemctl restart nginx
    systemctl enable nginx
  EOF

  tags = ["terraform", "demo", "web-server"]
}

# Add to main.tf (or create outputs.tf):

output "droplet_id" {
  description = "ID of the droplet"
  value       = digitalocean_droplet.web.id
}

output "droplet_ip_address" {
  description = "Public IPv4 address of the droplet"
  value       = digitalocean_droplet.web.ipv4_address
}

output "droplet_url" {
  description = "URL to access the web server"
  value       = "http://${digitalocean_droplet.web.ipv4_address}"
}

output "ssh_connection_string" {
  description = "SSH command to connect to the droplet"
  value       = "ssh -i ~/.ssh/terraform-demo root@${digitalocean_droplet.web.ipv4_address}"
}
